/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// Inner controller class for the order shipment bundling reporting job.
/// </summary>
class METOrderShipmentBundlingReportingJobInnerController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Initializes the object.
/// </summary>
void new()
{
    super(classStr(METOrderShipmentBundlingReportingJobService), 
          methodStr(METOrderShipmentBundlingReportingJobService, process), 
          SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Returns <c>METOrderShipmentBundlingReportingJobInnerController</c> object.
/// </summary>
/// <returns> <c>METOrderShipmentBundlingReportingJobInnerController</c>. </returns>
public static METOrderShipmentBundlingReportingJobInnerController construct()
{
    return new METOrderShipmentBundlingReportingJobInnerController();
}

/// <summary>
/// Starts the process.
/// </summary>
/// <param name = "_args">Args.</param>
public static void main(Args _args)
{
    METOrderShipmentBundlingReportingJobInnerController controller;

    controller = METOrderShipmentBundlingReportingJobInnerController::construct();

    controller.startOperation();
}

/// <summary>
/// Defines default caption.
/// </summary>
/// <returns>Default caption.</returns>
public str defaultCaption()
{
    return "@MET:OrderShipmentBundlingReportingJob";
}
